INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_09','V371','阮明',9,'我还有个疑问，这个挂失是临时的对吧？之后我补办新卡，还能保留原来的手机号吗？','wǒ hái yǒu gè yí wèn ， zhè ge guà shī shì lín shí de duì ba ？ zhī hòu wǒ bǔ bàn xīn kǎ ， hái néng bǎo liú yuán lái de shǒu jī hào ma ？','Em còn một thắc mắc nữa, việc báo mất này là tạm thời đúng không ạ? Sau này em làm lại SIM mới thì có giữ được số điện thoại cũ không?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_10','V371','客服',10,'可以的，您本人携带护照去任意线下营业厅，都可以补办同号的SIM卡。','kě yǐ de ， nín běn rén xié dài hù zhào qù rèn yì xiàn xià yíng yè tīng ， dōu kě yǐ bǔ bàn tóng hào de SIM kǎ 。','Được ạ, anh chỉ cần mang hộ chiếu đến bất kỳ cửa hàng giao dịch nào là có thể làm lại SIM cùng số.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_11','V371','阮明',11,'那补办需要花钱吗？是免费的还是要交工本费？','nà bǔ bàn xū yào huā qián ma ？ shì miǎn fèi de hái shì yào jiāo gōng běn fèi ？','Vậy làm lại SIM có mất tiền không ạ? Miễn phí hay phải đóng phí làm thẻ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_12','V371','客服',12,'首次挂失补卡是免收工本费的，只有一年内多次补办，才会收取相关费用。','shǒu cì guà shī bǔ kǎ shì miǎn shōu gōng běn fèi de ， zhǐ yǒu yī nián nèi duō cì bǔ bàn ， cái huì shōu qǔ xiāng guān fèi yòng 。','Lần đầu báo mất và làm lại SIM thì miễn phí, chỉ khi trong vòng một năm làm lại nhiều lần mới bị tính phí.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_13','V371','阮明',13,'原来是这样，我都清楚了，太感谢您帮忙紧急冻结卡号了。','yuán lái shì zhè yàng ， wǒ dōu qīng chǔ le ， tài gǎn xiè nín bāng máng jǐn jí dòng jié kǎ hào le 。','Ra là vậy, em rõ hết rồi ạ, cảm ơn chị nhiều vì đã giúp khóa khẩn cấp số của em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_14','V371','客服',14,'不用客气，后续补办有任何疑问，随时拨打我们的官方热线咨询即可。','bù yòng kè qì ， hòu xù bǔ bàn yǒu rèn hé yí wèn ， suí shí bō dǎ wǒ men de guān fāng rè xiàn zī xún jí kě 。','Không có gì, sau này làm lại có thắc mắc gì thì cứ gọi đường dây nóng chính thức của chúng tôi để được tư vấn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆；伤者骨折、出血不可随意挪动，防止二次伤害。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好！麻烦快点，这边有人摔倒受伤了，需要救护车！','nín hǎo ！ má fán kuài diǎn ， zhè biān yǒu rén shuāi dǎo shòu shāng le ， xū yào jiù hù chē ！','Alo! Xin nhanh lên giúp, ở đây có người bị ngã bị thương, cần xe cứu thương gấp!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'请您先保持冷静，不要慌张。告诉我准确的事发地址，还有伤者的具体情况。','qǐng nín xiān bǎo chí lěng jìng ， bú yào huāng zhāng 。 gào sù wǒ zhǔn què de shì fā dì zhǐ ， hái yǒu shāng zhě de jù tǐ qíng kuàng 。','Anh/chị bình tĩnh lại đã, đừng hoảng. Cho tôi biết địa chỉ chính xác nơi xảy ra sự việc, và tình trạng cụ thể của người bị thương.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'地点在大学南门的沿街小吃街，有人下楼梯摔下去了，腿流了很多血，现在站不起来。','dì diǎn zài dà xué nán mén de yán jiē xiǎo chī jiē ， yǒu rén xià lóu tī shuāi xià qù le ， tuǐ liú le hěn duō xuè ， xiàn zài zhàn bù qǐ lái 。','Địa điểm ở phố ăn vặt ven đường phía cổng nam trường đại học, có người bị ngã cầu thang, chân chảy rất nhiều máu, giờ không đứng dậy được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'切记千万不要挪动、拖拽伤者，很容易造成二次骨折损伤。救护车十分钟内就能到现场。','qiè jì qiān wàn bú yào nuó dòng 、 tuō zhuāi shāng zhě ， hěn róng yì zào chéng èr cì gǔ zhé sǔn shāng 。 jiù hù chē shí fēn zhōng nèi jiù néng dào xiàn chǎng 。','Nhớ kỹ tuyệt đối không được di chuyển, kéo lê người bị thương, rất dễ gây gãy xương lần hai. Xe cứu thương sẽ đến trong vòng mười phút.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'好的好的，我不碰他！我马上站在路口显眼的地方等着，给救护车引路。','hǎo de hǎo de ， wǒ bù pèng tā ！ wǒ mǎ shàng zhàn zài lù kǒu xiǎn yǎn de dì fāng děng zhe ， gěi jiù hù chē yǐn lù 。','Vâng vâng, em sẽ không đụng vào người đó! Em sẽ đứng ngay ở chỗ dễ thấy đầu đường đợi để dẫn đường cho xe cứu thương.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'辛苦您了，全程保持电话畅通。如果伤者出血量变大、意识变差，一定要立刻告诉我。','xīn kǔ nín le ， quán chéng bǎo chí diàn huà chàng tōng 。 rú guǒ shāng zhě chū xiě liàng biàn dà 、 yì shí biàn chà ， yí dìng yào lì kè gào sù wǒ 。','Cảm ơn anh/chị đã vất vả, giữ điện thoại thông suốt trong suốt quá trình. Nếu người bị thương chảy máu nhiều hơn hoặc ý thức kém đi thì phải báo ngay cho tôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'我明白，我现在用纸巾帮他按压伤口止血，目前人还是清醒的，没有迷糊。','wǒ míng bái ， wǒ xiàn zài yòng zhǐ jīn bāng tā àn yā shāng kǒu zhǐ xuè ， mù qián rén hái shì qīng xǐng de ， méi yǒu mí hū 。','Em hiểu rồi, em đang dùng khăn giấy ấn lên vết thương để cầm máu cho người đó, hiện tại người vẫn tỉnh táo, không lơ mơ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_08','V372','接线员',8,'很好，就保持持续按压止血，尽量减少失血，等待医护人员到场。','hěn hǎo ， jiù bǎo chí chí xù àn yā zhǐ xuè ， jǐn liàng jiǎn shǎo shī xuè ， děng dài yī hù rén yuán dào chǎng 。','Tốt lắm, cứ giữ ấn liên tục để cầm máu, cố gắng giảm thiểu mất máu, chờ nhân viên y tế đến.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_09','V372','阮明',9,'我会注意的，绝对不随便移动伤者，按照您说的做。','wǒ huì zhù yì de ， jué duì bù suí biàn yí dòng shāng zhě ， àn zhào nín shuō de zuò 。','Em sẽ chú ý, tuyệt đối không tùy tiện di chuyển người bị thương, em sẽ làm theo lời chị dặn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_10','V372','接线员',10,'救护车已经从医院出发了，距离现场只剩三分钟路程。','jiù hù chē yǐ jīng cóng yī yuàn chū fā le ， jù lí xiàn chǎng zhǐ shèng sān fēn zhōng lù chéng 。','Xe cứu thương đã xuất phát từ bệnh viện rồi, chỉ còn cách hiện trường ba phút đường đi thôi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_11','V372','阮明',11,'太好了，我现在就在校门口马路边等着，一会挥手示意车辆。','tài hǎo le ， wǒ xiàn zài jiù zài xiào mén kǒu mǎ lù biān děng zhe ， yī huì huī shǒu shì yì chē liàng 。','Tốt quá ạ, em đang đứng ở ven đường cổng trường đợi, lát nữa em sẽ vẫy tay ra hiệu cho xe.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_12','V372','接线员',12,'辛苦您现场帮忙看护，医护人员马上抵达。','xīn kǔ nín xiàn chǎng bāng máng kān hù ， yī hù rén yuán mǎ shàng dǐ dá 。','Cảm ơn anh/chị đã vất vả trông chừng tại chỗ, nhân viên y tế sắp đến nơi rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_13','V372','阮明',13,'好，我一直在这等着。','hǎo ， wǒ yì zhí zài zhè děng zhe 。','Vâng, em sẽ đứng đây đợi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖；国内宿舍厨房明令禁止无人看管明火，无人值守属于违规行为。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，不好了！公共厨房刚刚着火了！不过我已经把燃气总阀关掉了。','sù guǎn lǎo shī ， bù hǎo le ！ gōng gòng chú fáng gāng gāng zháo huǒ le ！ bù guò wǒ yǐ jīng bǎ rán qì zǒng fá guān diào le 。','Cô ơi, không hay rồi! Bếp chung vừa mới bị cháy! Nhưng em đã tắt van tổng gas rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',2,'着火了？你先别靠近灶台！我先问你，你有没有直接往火上浇水？','zháo huǒ le ？ nǐ xiān bié kào jìn zào tái ！ wǒ xiān wèn nǐ ， nǐ yǒu méi yǒu zhí jiē wǎng huǒ shàng jiāo shuǐ ？','Cháy à? Em đừng lại gần bếp nấu vội! Cô hỏi trước đã, em có đổ nước trực tiếp lên lửa không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',3,'没有没有！我参加过宿舍安全培训，知道油锅起火不能泼水，我马上拿锅盖把锅盖住，隔绝氧气灭火了。','méi yǒu méi yǒu ！ wǒ cān jiā guò sù shè ān quán péi xùn ， zhī dào yóu guō qǐ huǒ bù néng pō shuǐ ， wǒ mǎ shàng ná guō gài bǎ guō gài zhù ， gé jué yǎng qì miè huǒ le 。','Không có ạ, không có! Em từng tham gia tập huấn an toàn ký túc xá, biết chảo dầu bốc cháy thì không được đổ nước, em lấy nắp đậy chảo lại ngay để cách ly oxy dập lửa rồi ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',4,'还好你懂常识，没乱操作，不然火势一下子就蔓延开了。我现在拿灭火器马上过去。','hái hǎo nǐ dǒng cháng shí ， méi luàn cāo zuò ， bù rán huǒ shì yī xià zi jiù màn yán kāi le 。 wǒ xiàn zài ná miè huǒ qì mǎ shàng guò qù 。','May mà em biết kiến thức cơ bản, không xử lý bừa, chứ không thì lửa đã lan nhanh rồi. Cô lấy bình cứu hỏa qua ngay đây.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',5,'明火已经灭了，就是墙面有点被熏黑。我刚刚看了一圈，橱柜、纸巾这些易燃物都没烧到，应该没事吧？','míng huǒ yǐ jīng miè le ， jiù shì qiáng miàn yǒu diǎn bèi xūn hēi 。 wǒ gāng gāng kàn le yī quān ， chú guì 、 zhǐ jīn zhè xiē yì rán wù dōu méi shāo dào ， yīng gāi méi shì ba ？','Ngọn lửa đã tắt rồi ạ, chỉ là tường bị ám khói đen một chút thôi. Em vừa nhìn quanh một vòng, tủ bếp, giấy vệ sinh mấy thứ dễ cháy đều không bị cháy tới, chắc không sao đâu ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',6,'先别大意，厨房火情最怕复燃，不能光看表面。你确定锅里完全没有余火、火星了吗？','xiān bié dà yì ， chú fáng huǒ qíng zuì pà fù rán ， bù néng guāng kàn biǎo miàn 。 nǐ què dìng guō lǐ wán quán méi yǒu yú huǒ 、 huǒ xīng le ma ？','Đừng chủ quan vội, cháy bếp sợ nhất là bùng lại, không thể chỉ nhìn bề ngoài. Em chắc chắn trong nồi hoàn toàn không còn tàn lửa, tia lửa nào chứ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',7,'我仔细看过了，锅里彻底凉了，没有一点火星。这次是我的问题，我熬汤的时候走开了几分钟，水烧干才着的火。','wǒ zǐ xì kàn guò le ， guō lǐ chè dǐ liáng le ， méi yǒu yì diǎn huǒ xīng 。 zhè cì shì wǒ de wèn tí ， wǒ áo tāng de shí hòu zǒu kāi le jǐ fēn zhōng ， shuǐ shāo gàn cái zhe de huǒ 。','Em xem kỹ rồi ạ, trong nồi nguội hẳn rồi, không còn chút tia lửa nào. Lần này là lỗi của em, lúc ninh canh em rời đi vài phút, nước cạn hết mới bị cháy.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_08','V373','宿管老师',8,'我就说，宿舍公共厨房明文规定，用火必须有人看管，无人值守本来就是违规的，特别容易出事。','wǒ jiù shuō ， sù shè gōng gòng chú fáng míng wén guī dìng ， yòng huǒ bì xū yǒu rén kān guǎn ， wú rén zhí shǒu běn lái jiù shì wéi guī de ， tè bié róng yì chū shì 。','Cô đã nói rồi, bếp chung ký túc xá có quy định rõ ràng, dùng lửa bắt buộc phải có người trông, không có ai trông coi vốn dĩ đã là vi phạm rồi, rất dễ xảy ra chuyện.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_09','V373','阮明',9,'我知道错了，以后做饭绝对不擅自离开灶台了，一定全程看着。','wǒ zhī dào cuò le ， yǐ hòu zuò fàn jué duì bù shàn zì lí kāi zào tái le ， yí dìng quán chéng kàn zhe 。','Em biết lỗi rồi ạ, sau này nấu ăn tuyệt đối sẽ không tự ý rời khỏi bếp nữa, nhất định sẽ trông coi suốt quá trình.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_10','V373','宿管老师',10,'我马上到现场仔细检查一遍，确认没有复燃隐患，大家才能继续用厨房。','wǒ mǎ shàng dào xiàn chǎng zǐ xì jiǎn chá yī biàn ， què rèn méi yǒu fù rán yǐn huàn ， dà jiā cái néng jì xù yòng chú fáng 。','Cô sẽ đến hiện trường kiểm tra kỹ ngay, xác nhận không còn nguy cơ bùng cháy lại thì mọi người mới được tiếp tục dùng bếp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_11','V373','阮明',11,'老师，需要我留在这边配合您检查、说明情况吗？','lǎo shī ， xū yào wǒ liú zài zhè biān pèi hé nín jiǎn chá 、 shuō míng qíng kuàng ma ？','Cô ơi, em có cần ở lại đây phối hợp cô kiểm tra, trình bày tình hình không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_12','V373','宿管老师',12,'不用，你直接来值班室等着就行，我检查完跟你说后续的注意事项。','bù yòng ， nǐ zhí jiē lái zhí bān shì děng zhe jiù xíng ， wǒ jiǎn chá wán gēn nǐ shuō hòu xù de zhù yì shì xiàng 。','Không cần, em cứ đến phòng trực đợi là được, cô kiểm tra xong sẽ nói với em những điều cần lưu ý sau đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_13','V373','阮明',13,'实在抱歉，给您添麻烦了，都是我的疏忽。','shí zài bào qiàn ， gěi nín tiān má fán le ， dōu shì wǒ de shū hū 。','Em thật sự xin lỗi, làm phiền cô rồi, đều là do em sơ suất.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_14','V373','宿管老师',14,'吸取教训就好，宿舍安全永远是第一位的，不用太自责。','xī qǔ jiào xùn jiù hǎo ， sù shè ān quán yǒng yuǎn shì dì yī wèi de ， bù yòng tài zì zé 。','Rút kinh nghiệm là được rồi, an toàn ký túc xá luôn là ưu tiên hàng đầu, em không cần tự trách mình quá.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场；外籍当事人护照可作为辅助身份凭证上传备案。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好，我要报备一起交通事故，主干道十字路口两车轻微剐蹭，没有人受伤。','nín hǎo ， wǒ yào bào bèi yì qǐ jiāo tōng shì gù ， zhǔ gàn dào shí zì lù kǒu liǎng chē qīng wēi guǎ cèng ， méi yǒu rén shòu shāng 。','Chào anh, tôi muốn trình báo một vụ tai nạn giao thông, hai xe va quẹt nhẹ ở ngã tư đường chính, không có ai bị thương.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'您好，我跟你说两个关键步骤，你们先把车挪到路边非机动车道，不要堵路，然后多角度拍好现场照片留存证据。','nín hǎo ， wǒ gēn nǐ shuō liǎng gè guān jiàn bù zhòu ， nǐ men xiān bǎ chē nuó dào lù biān fēi jī dòng chē dào ， bú yào dǔ lù ， rán hòu duō jiǎo dù pāi hǎo xiàn chǎng zhào piān liú cún zhèng jù 。','Chào anh/chị, tôi hướng dẫn hai bước quan trọng nhé, trước tiên hai bên di chuyển xe vào làn đường không cơ giới ven đường, không để chắn đường, sau đó chụp ảnh hiện trường ở nhiều góc độ để lưu làm bằng chứng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'好的，我们已经把车停到不影响交通的位置了，前后、侧面、碰撞点的照片都拍齐全了。','hǎo de ， wǒ men yǐ jīng bǎ chē tíng dào bù yǐng xiǎng jiāo tōng de wèi zhì le ， qián hòu 、 cè miàn 、 pèng zhuàng diǎn de zhào piān dōu pāi qí quán le 。','Vâng, chúng tôi đã đỗ xe vào vị trí không ảnh hưởng giao thông rồi, ảnh chụp mặt trước, sau, bên hông, điểm va chạm đều đã chụp đầy đủ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','交警接线员',4,'无人员伤亡的轻微剐蹭事故，不用我们线下出警，直接在交管线上平台就能快速定责处理。','wú rén yuán shāng wáng de qīng wēi guǎ cèng shì gù ， bù yòng wǒ men xiàn xià chū jǐng ， zhí jiē zài jiāo guǎn xiàn shàng píng tái jiù néng kuài sù dìng zé chǔ lǐ 。','Vụ va quẹt nhẹ không có thương vong thì không cần chúng tôi đến hiện trường, chỉ cần làm trực tiếp trên nền tảng trực tuyến của cơ quan giao thông là có thể xác định trách nhiệm nhanh chóng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'了解了。那线上处理需要上传哪些证件？我是外国留学生，我的护照可以当作有效证件用吗？','liǎo jiě le 。 nà xiàn shàng chǔ lǐ xū yào shàng chuán nǎ xiē zhèng jiàn ？ wǒ shì wài guó liú xué shēng ， wǒ de hù zhào kě yǐ dàng zuò yǒu xiào zhèng jiàn yòng ma ？','Tôi hiểu rồi. Vậy xử lý trực tuyến cần tải lên những giấy tờ gì? Tôi là du học sinh nước ngoài, hộ chiếu của tôi có thể dùng làm giấy tờ hợp lệ không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','交警接线员',6,'可以的，完全没问题。需要上传机动车行驶证、驾驶员驾驶证，再加上你的护照照片即可。','kě yǐ de ， wán quán méi wèn tí 。 xū yào shàng chuán jī dòng chē xíng shǐ zhèng 、 jià shǐ yuán jià shǐ zhèng ， zài jiā shàng nǐ de hù zhào zhào piān jí kě 。','Được ạ, hoàn toàn không vấn đề gì. Anh/chị cần tải lên giấy đăng ký xe, bằng lái xe của người điều khiển, cộng thêm ảnh hộ chiếu của anh/chị là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'那定责之后，理赔也是线上操作吗？不用跑去交警大队线下办理吧？','nà dìng zé zhī hòu ， lǐ péi yě shì xiàn shàng cāo zuò ma ？ bù yòng pǎo qù jiāo jǐng dà duì xiàn xià bàn lǐ ba ？','Vậy sau khi xác định trách nhiệm rồi, việc bồi thường cũng làm trực tuyến à? Không cần chạy đến đội cảnh sát giao thông làm trực tiếp chứ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_08','V374','交警接线员',8,'对的，全责方的保险公司会线上对接理赔，全程线上办结，不用线下跑腿。','duì de ， quán zé fāng de bǎo xiǎn gōng sī huì xiàn shàng duì jiē lǐ péi ， quán chéng xiàn shàng bàn jié ， bù yòng xiàn xià pǎo tuǐ 。','Đúng vậy, công ty bảo hiểm của bên chịu trách nhiệm hoàn toàn sẽ kết nối bồi thường trực tuyến, xử lý xong toàn bộ qua mạng, không cần đi lại trực tiếp.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_09','V374','阮明',9,'太好了，那我现在就和对方车主整理证件照片，马上上传小程序。','tài hǎo le ， nà wǒ xiàn zài jiù hé duì fāng chē zhǔ zhěng lǐ zhèng jiàn zhào piān ， mǎ shàng shàng chuán xiǎo chéng xù 。','Tốt quá, vậy bây giờ tôi sẽ cùng chủ xe bên kia chuẩn bị ảnh giấy tờ, tải lên ứng dụng ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_10','V374','交警接线员',10,'上传之后等待系统线上审核就行，一般半小时内就会出具责任认定书。','shàng chuán zhī hòu děng dài xì tǒng xiàn shàng shěn hé jiù xíng ， yì bān bàn xiǎo shí nèi jiù huì chū jù zé rèn rèn dìng shū 。','Sau khi tải lên chỉ cần chờ hệ thống thẩm định trực tuyến là được, thường trong nửa tiếng sẽ có văn bản xác định trách nhiệm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_11','V374','阮明',11,'好的，流程我都清楚了。','hǎo de ， liú chéng wǒ dōu qīng chǔ le 。','Vâng, tôi đã rõ hết quy trình rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_12','V374','交警接线员',12,'后续如果理赔有纠纷，随时拨打热线咨询。','hòu xù rú guǒ lǐ péi yǒu jiū fēn ， suí shí bō dǎ rè xiàn zī xún 。','Sau này nếu có tranh chấp về bồi thường, cứ gọi đường dây nóng để được tư vấn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_13','V374','阮明',13,'明白，谢谢您。','míng bái ， xiè xiè nín 。','Tôi hiểu rồi, cảm ơn anh.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程；完整聊天、转账截图是关键办案证据，不可删除。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我被网络诈骗了！被虚假客服诱导转了账，钱已经转出去了，能不能帮忙拦截一下？','nín hǎo ， wǒ bèi wǎng luò zhà piàn le ！ bèi xū jiǎ kè fú yòu dǎo zhuǎn liǎo zhàng ， qián yǐ jīng zhuǎn chū qù le ， néng bù néng bāng máng lán jié yī xià ？','Alo, tôi bị lừa đảo qua mạng rồi! Bị nhân viên chăm sóc khách hàng giả mạo dụ chuyển khoản, tiền đã chuyển đi rồi, có thể giúp tôi chặn lại được không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',2,'您先别慌，立刻告诉我三个关键信息：对方的收款账号、准确的转账时间、还有转账总金额。','nín xiān bié huāng ， lì kè gào sù wǒ sān gè guān jiàn xìn xī ： duì fāng de shōu kuǎn zhàng hào 、 zhǔn què de zhuǎn zhàng shí jiān 、 hái yǒu zhuǎn zhàng zǒng jīn é 。','Anh/chị bình tĩnh đã, cho tôi biết ngay ba thông tin quan trọng: số tài khoản nhận tiền của đối phương, thời gian chuyển khoản chính xác, và tổng số tiền đã chuyển.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',3,'好的好的，我马上找记录！我转完账一秒就反应过来是骗子了，想撤回交易，但是系统提示撤回失败。','hǎo de hǎo de ， wǒ mǎ shàng zhǎo jì lù ！ wǒ zhuǎn wán zhàng yī miǎo jiù fǎn yìng guò lái shì piàn zi le ， xiǎng chè huí jiāo yì ， dàn shì xì tǒng tí shì chè huí shī bài 。','Vâng vâng, tôi tìm lịch sử giao dịch ngay! Vừa chuyển xong tôi nhận ra ngay là bị lừa, muốn hủy giao dịch nhưng hệ thống báo hủy không thành công.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',4,'我先跟您说明一下，资金一旦成功转入私人账户，用户是无法自主撤回的，我现在立刻提交冻结指令，锁定对方账户。','wǒ xiān gēn nín shuō míng yī xià ， zī jīn yí dàn chéng gōng zhuǎn rù sī rén zhàng hù ， yòng hù shì wú fǎ zì zhǔ chè huí de ， wǒ xiàn zài lì kè tí jiāo dòng jié zhǐ lìng ， suǒ dìng duì fāng zhàng hù 。','Tôi giải thích trước với anh/chị, một khi tiền đã chuyển thành công vào tài khoản cá nhân thì người dùng không thể tự hủy được, bây giờ tôi sẽ gửi lệnh phong tỏa ngay để khóa tài khoản của đối phương.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',5,'啊？那还能追回吗？冻结之后，我转出去的钱还有机会找回来吗？','a ？ nà hái néng zhuī huí ma ？ dòng jié zhī hòu ， wǒ zhuǎn chū qù de qián hái yǒu jī huì zhǎo huí lái ma ？','Ơ? Vậy còn lấy lại được không? Sau khi phong tỏa, số tiền tôi đã chuyển đi có cơ hội tìm lại được không?','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',6,'只能冻结对方账户里还没被转走的剩余资金，已经流转的资金需要后续配合警方追查。现在最关键的是你要去派出所做报案笔录留存证据。','zhǐ néng dòng jié duì fāng zhàng hù lǐ hái méi bèi zhuǎn zǒu de shèng yú zī jīn ， yǐ jīng liú zhuǎn de zī jīn xū yào hòu xù pèi hé jǐng fāng zhuī chá 。 xiàn zài zuì guān jiàn de shì nǐ yào qù pài chū suǒ zuò bào àn bǐ lù liú cún zhèng jù 。','Chỉ có thể phong tỏa số tiền còn lại chưa bị chuyển đi trong tài khoản đối phương, số tiền đã lưu chuyển thì cần phối hợp với công an điều tra sau. Bây giờ quan trọng nhất là anh/chị phải đến đồn công an lập biên bản trình báo để lưu bằng chứng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',7,'那我要去哪个派出所？需要带什么证件过去办理？','nà wǒ yào qù nǎ ge pài chū suǒ ？ xū yào dài shén me zhèng jiàn guò qù bàn lǐ ？','Vậy tôi phải đến đồn công an nào? Cần mang giấy tờ gì đến làm thủ tục?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_08','V375','反诈客服',8,'带上你的本人护照，去你就近的辖区派出所就行，工作人员会对接我们反诈中心留存线索。','dài shàng nǐ de běn rén hù zhào ， qù nǐ jiù jìn de xiá qū pài chū suǒ jiù xíng ， gōng zuò rén yuán huì duì jiē wǒ men fǎn zhà zhōng xīn liú cún xiàn suǒ 。','Mang theo hộ chiếu của anh/chị, đến đồn công an khu vực gần nhất là được, nhân viên ở đó sẽ kết nối với trung tâm chống lừa đảo của chúng tôi để lưu manh mối.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_09','V375','阮明',9,'做完笔录之后，警方会一直跟进追查这个诈骗账户吗？','zuò wán bǐ lù zhī hòu ， jǐng fāng huì yì zhí gēn jìn zhuī chá zhè ge zhà piàn zhàng hù ma ？','Sau khi lập biên bản xong, công an có tiếp tục theo dõi điều tra tài khoản lừa đảo này không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_10','V375','反诈客服',10,'会的，所有涉案线索都会登记备案，警方会持续追踪资金流向，尽力帮你挽回损失。','huì de ， suǒ yǒu shè àn xiàn suǒ dōu huì dēng jì bèi àn ， jǐng fāng huì chí xù zhuī zōng zī jīn liú xiàng ， jìn lì bāng nǐ wǎn huí sǔn shī 。','Có ạ, tất cả manh mối liên quan đến vụ việc đều sẽ được ghi nhận lưu hồ sơ, công an sẽ tiếp tục theo dõi dòng tiền, cố gắng hết sức giúp anh/chị giảm thiểu thiệt hại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_11','V375','阮明',11,'好，我马上查附近派出所地址，现在就过去报案。','hǎo ， wǒ mǎ shàng chá fù jìn pài chū suǒ dì zhǐ ， xiàn zài jiù guò qù bào àn 。','Vâng, tôi sẽ tra ngay địa chỉ đồn công an gần đây, đi trình báo luôn bây giờ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_12','V375','反诈客服',12,'一定要保存好所有证据，转账截图、聊天记录都不要删除，办案需要用到。','yí dìng yào bǎo cún hǎo suǒ yǒu zhèng jù ， zhuǎn zhàng jié tú 、 liáo tiān jì lù dōu bú yào shān chú ， bàn àn xū yào yòng dào 。','Nhất định phải lưu giữ toàn bộ bằng chứng, ảnh chụp màn hình chuyển khoản, lịch sử trò chuyện đều không được xóa, sẽ cần dùng đến khi xử lý vụ việc.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_13','V375','阮明',13,'我都存好了，一份没删。','wǒ dōu cún hǎo le ， yī fèn méi shān 。','Tôi lưu hết rồi, không xóa cái nào cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_14','V375','反诈客服',14,'后续案件的进展，派出所会第一时间通知你。','hòu xù àn jiàn de jìn zhǎn ， pài chū suǒ huì dì yī shí jiān tōng zhī nǐ 。','Về sau có tiến triển gì của vụ án, đồn công an sẽ thông báo cho anh/chị ngay lập tức.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为撬动、暴力损坏门锁，则需自行支付配件与工时费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'师傅您好，我公寓的门锁坏了，钥匙插进去转不动，我进不去房间了。','shī fù nín hǎo ， wǒ gōng yù de mén suǒ huài le ， yào shi chā jìn qù zhuǎn bù dòng ， wǒ jìn bù qù fáng jiān le 。','Chào chú, khóa cửa căn hộ của em bị hỏng rồi, tra chìa vào mà xoay không được, em không vào phòng được ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'我先问清楚情况，你之前有没有用力掰钥匙、大力敲门锁之类的操作？','wǒ xiān wèn qīng chǔ qíng kuàng ， nǐ zhī qián yǒu méi yǒu yòng lì bāi yào shi 、 dà lì qiāo mén suǒ zhī lèi de cāo zuò ？','Để chú hỏi rõ tình hình đã nhé, trước đó em có bẻ mạnh chìa khóa hay đập mạnh vào ổ khóa gì không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'没有的，我都是轻轻插钥匙、慢慢转，一点暴力操作都没有，完全不是我人为弄坏的。','méi yǒu de ， wǒ dōu shì qīng qīng chā yào shi 、 màn màn zhuǎn ， yì diǎn bào lì cāo zuò dōu méi yǒu ， wán quán bú shì wǒ rén wéi nòng huài de 。','Dạ không có ạ, em toàn tra chìa nhẹ nhàng rồi xoay từ từ thôi, không hề dùng lực mạnh, tuyệt đối không phải do em làm hỏng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'行，那你先在楼下单元门等着，我带上工具，十分钟之内到你楼下。','xíng ， nà nǐ xiān zài lóu xià dān yuán mén děng zhe ， wǒ dài shàng gōng jù ， shí fēn zhōng zhī nèi dào nǐ lóu xià 。','Được rồi, vậy em cứ đứng chờ ở cửa tòa nhà tầng dưới nhé, chú mang đồ nghề qua, trong vòng mười phút là tới.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'师傅，我补充一下，我家里三把备用钥匙我都试过了，全都转不动，锁芯应该是彻底卡死了。','shī fù ， wǒ bǔ chōng yī xià ， wǒ jiā lǐ sān bǎ bèi yòng yào shi wǒ dōu shì guò le ， quán dōu zhuǎn bù dòng ， suǒ xīn yīng gāi shì chè dǐ kǎ sǐ le 。','Chú ơi, em bổ sung thêm là ba chiếc chìa khóa dự phòng ở nhà em đều đã thử qua rồi, đều xoay không được, chắc ổ khóa bị kẹt cứng luôn rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'我大概清楚了，大概率是锁芯内部零件老化断裂，这种情况一般需要直接更换整套门锁。','wǒ dà gài qīng chǔ le ， dà gài lǜ shì suǒ xīn nèi bù líng jiàn lǎo huà duàn liè ， zhè zhǒng qíng kuàng yì bān xū yào zhí jiē gēng huàn zhěng tào mén suǒ 。','Chú hiểu sơ sơ rồi, khả năng cao là linh kiện bên trong ổ khóa bị lão hóa gãy rồi, trường hợp này thường phải thay nguyên bộ khóa cửa.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'那我想问一下，换锁的配件费和人工费，是需要我自己出吗？','nà wǒ xiǎng wèn yī xià ， huàn suǒ de pèi jiàn fèi hé rén gōng fèi ， shì xū yào wǒ zì jǐ chū ma ？','Vậy cho em hỏi, tiền linh kiện với tiền công thay khóa thì em có phải tự chi trả không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_08','V376','维修专员',8,'这个要看损坏原因。房子设施自然老化故障，物业免费修；如果是租客暴力损坏，才需要自费。','zhè ge yào kàn sǔn huài yuán yīn 。 fáng zi shè shī zì rán lǎo huà gù zhàng ， wù yè miǎn fèi xiū ； rú guǒ shì zū kè bào lì sǔn huài ， cái xū yào zì fèi 。','Cái này còn tùy nguyên nhân hư hỏng. Nếu thiết bị nhà tự nhiên xuống cấp thì bên quản lý sửa miễn phí; còn nếu do người thuê làm hỏng do dùng lực mạnh thì mới phải tự bỏ tiền.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_09','V376','阮明',9,'我真的全程轻轻操作，没有磕碰撬动，这肯定是自然老化吧？','wǒ zhēn de quán chéng qīng qīng cāo zuò ， méi yǒu kē pèng qiào dòng ， zhè kěn dìng shì zì rán lǎo huà ba ？','Em thao tác nhẹ nhàng suốt từ đầu đến cuối, không hề va đập hay cạy phá gì cả, chắc chắn là do tự nhiên xuống cấp rồi đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_10','V376','维修专员',10,'我到现场看过锁体磨损情况才能最终判定，只要是自然老化，你不用花一分钱。','wǒ dào xiàn chǎng kàn guò suǒ tǐ mó sǔn qíng kuàng cái néng zuì zhōng pàn dìng ， zhǐ yào shì zì rán lǎo huà ， nǐ bù yòng huā yī fēn qián 。','Chú phải đến tận nơi xem tình trạng mòn của ổ khóa mới kết luận chính xác được, nhưng nếu đúng là do lão hóa tự nhiên thì em không phải trả một đồng nào cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_11','V376','阮明',11,'好的，那我就在楼下等着您。','hǎo de ， nà wǒ jiù zài lóu xià děng zhe nín 。','Dạ vâng, vậy em đứng chờ chú ở dưới nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_12','V376','维修专员',12,'马上出发，到了我给你打电话。','mǎ shàng chū fā ， dào le wǒ gěi nǐ dǎ diàn huà 。','Chú xuất phát ngay đây, tới nơi chú gọi điện cho em.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照；现场自助拍照符合涉外证件标准，无需提前线下照相馆拍摄。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，我的越南护照不小心弄丢了，想来这边办理临时出入境通行证明。','nín hǎo ， wǒ de yuè nán hù zhào bù xiǎo xīn nòng diū le ， xiǎng lái zhè biān bàn lǐ lín shí chū rù jìng tōng xíng zhèng míng 。','Chào chị, hộ chiếu Việt Nam của em không may bị mất rồi, em muốn đến làm giấy chứng nhận xuất nhập cảnh tạm thời ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'办理临时通行证明需要两样必备材料，派出所开的遗失回执，还有一寸白底证件照。','bàn lǐ lín shí tōng xíng zhèng míng xū yào liǎng yàng bì bèi cái liào ， pài chū suǒ kāi de yí shī huí zhí ， hái yǒu yī cùn bái dǐ zhèng jiàn zhào 。','Để làm giấy chứng nhận tạm thời cần hai loại giấy tờ bắt buộc, đó là biên nhận trình báo mất do công an phường cấp, và ảnh thẻ nền trắng cỡ một tấc.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'派出所的回执我带了，一直揣在身上。但是太着急过来，我忘记准备证件照了。','pài chū suǒ de huí zhí wǒ dài le ， yì zhí chuāi zài shēn shàng 。 dàn shì tài zháo jí guò lái ， wǒ wàng jì zhǔn bèi zhèng jiàn zhào le 。','Biên nhận của công an phường em có mang theo, luôn giữ bên người. Nhưng vì vội quá nên em quên chuẩn bị ảnh thẻ mất rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',4,'没带也没关系，我们大厅入口有自助拍照机，专门拍涉外证件照片，规格都是达标，二十元一套。','méi dài yě méi guān xì ， wǒ men dà tīng rù kǒu yǒu zì zhù pāi zhào jī ， zhuān mén pāi shè wài zhèng jiàn zhào piān ， guī gé dōu shì dá biāo ， èr shí yuán yī tào 。','Không mang theo cũng không sao, ở lối vào sảnh có máy chụp ảnh tự động, chuyên chụp ảnh giấy tờ cho người nước ngoài, quy cách đều đạt chuẩn, hai mươi tệ một bộ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',5,'那太好了。我拍完照片、提交所有材料，今天能直接拿到临时证明吗？','nà tài hǎo le 。 wǒ pāi wán zhào piān 、 tí jiāo suǒ yǒu cái liào ， jīn tiān néng zhí jiē ná dào lín shí zhèng míng ma ？','Vậy tốt quá ạ. Sau khi em chụp ảnh xong và nộp đầy đủ giấy tờ, hôm nay có thể lấy được giấy chứng nhận tạm thời luôn không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',6,'材料齐全的话，窗口是当场办结出证的，不用排队等候。','cái liào qí quán de huà ， chuāng kǒu shì dāng chǎng bàn jié chū zhèng de ， bù yòng pái duì děng hòu 。','Nếu giấy tờ đầy đủ thì quầy sẽ xử lý và cấp ngay tại chỗ, không cần xếp hàng chờ đợi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',7,'我再确认一下，这个临时证明有效期多久？可以用来回国、补办护照吗？','wǒ zài què rèn yī xià ， zhè ge lín shí zhèng míng yǒu xiào qī duō jiǔ ？ kě yǐ yòng lái huí guó 、 bǔ bàn hù zhào ma ？','Em xác nhận lại nhé, giấy chứng nhận tạm thời này có hiệu lực bao lâu ạ? Có thể dùng để về nước hay làm lại hộ chiếu không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_08','V377','工作人员',8,'有效期三十天，既可以用来搭乘国际航班出境回国，也能用于去驻华大使馆补办正式护照。','yǒu xiào qī sān shí tiān ， jì kě yǐ yòng lái dā chéng guó jì háng bān chū jìng huí guó ， yě néng yòng yú qù zhù huá dà shǐ guǎn bǔ bàn zhèng shì hù zhào 。','Hiệu lực ba mươi ngày, vừa có thể dùng để lên chuyến bay quốc tế về nước, vừa có thể dùng để đến đại sứ quán làm lại hộ chiếu chính thức.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_09','V377','阮明',9,'没问题，那我现在去拍照，拍完马上回来交材料。','méi wèn tí ， nà wǒ xiàn zài qù pāi zhào ， pāi wán mǎ shàng huí lái jiāo cái liào 。','Không vấn đề gì, vậy giờ em đi chụp ảnh, chụp xong em quay lại nộp giấy tờ ngay ạ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_10','V377','工作人员',10,'你拍照的时候注意核对一下人像清晰度和尺寸，不合格的话需要重拍，耽误时间。','nǐ pāi zhào de shí hòu zhù yì hé duì yī xià rén xiàng qīng xī dù hé chǐ cùn ， bù hé gé de huà xū yào chóng pāi ， dān wù shí jiān 。','Lúc chụp ảnh em chú ý kiểm tra kỹ độ nét của khuôn mặt và kích thước ảnh nhé, nếu không đạt sẽ phải chụp lại, mất thời gian lắm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_11','V377','阮明',11,'好，我一定仔细核对，保证照片合格。','hǎo ， wǒ yí dìng zǐ xì hé duì ， bǎo zhèng zhào piān hé gé 。','Dạ, em nhất định sẽ kiểm tra kỹ, đảm bảo ảnh đạt chuẩn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_12','V377','工作人员',12,'拍完直接去三号窗口递交材料就行。','pāi wán zhí jiē qù sān hào chuāng kǒu dì jiāo cái liào jiù xíng 。','Chụp xong thì đến thẳng quầy số ba nộp giấy tờ là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助，包含对接家属、证件补办、事故手续协调等服务。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好，我是在中国读书的越南留学生，我遇到了严重的交通事故，想寻求大使馆的帮助。','nín hǎo ， wǒ shì zài zhōng guó dú shū de yuè nán liú xué shēng ， wǒ yù dào le yán zhòng de jiāo tōng shì gù ， xiǎng xún qiú dà shǐ guǎn de bāng zhù 。','Xin chào, tôi là du học sinh Việt Nam đang học tại Trung Quốc, tôi vừa gặp một vụ tai nạn giao thông nghiêm trọng, muốn nhờ đại sứ quán giúp đỡ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'您好，请您保持冷静，依次告诉我您的姓名、就读学校，还有事故发生的具体地点。','nín hǎo ， qǐng nín bǎo chí lěng jìng ， yī cì gào sù wǒ nín de xìng míng 、 jiù dú xué xiào ， hái yǒu shì gù fā shēng de jù tǐ dì diǎn 。','Chào bạn, mong bạn giữ bình tĩnh, hãy lần lượt cho tôi biết họ tên, trường đang theo học, và địa điểm cụ thể xảy ra tai nạn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我叫阮明，在本市高校读汉语言专业。事故发生在市中心主干道十字路口，现在交警和救护车都已经到现场处理了。','wǒ jiào ruǎn míng ， zài běn shì gāo xiào dú hàn yǔ yán zhuān yè 。 shì gù fā shēng zài shì zhōng xīn zhǔ gàn dào shí zì lù kǒu ， xiàn zài jiāo jǐng hé jiù hù chē dōu yǐ jīng dào xiàn chǎng chǔ lǐ le 。','Tôi tên Nguyễn Minh, đang học ngành tiếng Trung tại một trường đại học ở thành phố này. Tai nạn xảy ra ở ngã tư trục đường chính trung tâm thành phố, hiện cảnh sát giao thông và xe cứu thương đã có mặt xử lý rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'收到，我们会立刻对接当地辖区交警大队，跟进本次事故的全部处置流程，协助你处理后续手续。','shōu dào ， wǒ men huì lì kè duì jiē dāng dì xiá qū jiāo jǐng dà duì ， gēn jìn běn cì shì gù de quán bù chǔ zhì liú chéng ， xié zhù nǐ chǔ lǐ hòu xù shǒu xù 。','Đã nhận được thông tin, chúng tôi sẽ lập tức liên hệ với đội cảnh sát giao thông khu vực sở tại, theo sát toàn bộ quá trình xử lý vụ việc này, hỗ trợ bạn giải quyết các thủ tục tiếp theo.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'我想咨询一下，后续的治疗、证件补办，还有联系我国内家属这些事，大使馆都能帮忙协助吗？','wǒ xiǎng zī xún yī xià ， hòu xù de zhì liáo 、 zhèng jiàn bǔ bàn ， hái yǒu lián xì wǒ guó nèi jiā shǔ zhè xiē shì ， dà shǐ guǎn dōu néng bāng máng xié zhù ma ？','Tôi muốn hỏi thêm, việc điều trị sau này, làm lại giấy tờ, rồi liên hệ với người thân trong nước của tôi, những việc đó đại sứ quán có thể hỗ trợ được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'可以的。本国公民在境外遭遇重大人身意外，驻华大使馆都会提供全套的领事协助服务，涵盖你说的这些事宜。','kě yǐ de 。 běn guó gōng mín zài jìng wài zāo yù zhòng dà rén shēn yì wài ， zhù huá dà shǐ guǎn dōu huì tí gōng quán tào de lǐng shì xié zhù fú wù ， hán gài nǐ shuō de zhè xiē shì yí 。','Được. Công dân nước mình gặp sự cố nghiêm trọng về thân thể ở nước ngoài thì đại sứ quán tại đây đều sẽ cung cấp đầy đủ dịch vụ hỗ trợ lãnh sự, bao gồm cả những việc bạn vừa nói.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'目前伤者还在做医护检查，伤情还没确定，后续有新情况我会再打电话汇报。','mù qián shāng zhě hái zài zuò yī hù jiǎn chá ， shāng qíng hái méi què dìng ， hòu xù yǒu xīn qíng kuàng wǒ huì zài dǎ diàn huà huì bào 。','Hiện tại người bị thương vẫn đang được kiểm tra y tế, tình trạng thương tích chưa xác định được, có tình hình mới tôi sẽ gọi điện báo lại ngay.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_08','V378','接线员',8,'你记一下我们的官方热线，后续办理手续遇到任何难题，随时来电咨询。','nǐ jì yī xià wǒ men de guān fāng rè xiàn ， hòu xù bàn lǐ shǒu xù yù dào rèn hé nán tí ， suí shí lái diàn zī xún 。','Bạn ghi lại số đường dây nóng chính thức của chúng tôi nhé, sau này làm thủ tục gặp bất kỳ khó khăn gì cứ gọi điện hỏi bất cứ lúc nào.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_09','V378','阮明',9,'好的，我马上保存号码。','hǎo de ， wǒ mǎ shàng bǎo cún hào mǎ 。','Vâng, tôi lưu số ngay đây.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_10','V378','接线员',10,'祝你平安，有进展及时沟通。','zhù nǐ píng ān， yǒu jìn zhǎn jí shí gōu tōng。','Chúc bạn bình an, có tiến triển gì thì báo lại kịp thời nhé.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê, mình muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian, không biết trình bày sao cho hợp lý nữa.','AM05') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','CV chia thành ba phần chính là thông tin cơ bản, trình độ ngôn ngữ và kinh nghiệm thực tế là được rồi.','AM02') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm visa và giấy phép làm thêm hợp pháp không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Nhất định phải ghi vào, nhiều nơi tuyển dụng không nắm rõ quy định làm thêm của du học sinh đâu.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Mình viết xong một bản nháp rồi, nhưng phần kinh nghiệm thực tế viết sơ sài quá.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho mình, mình sẽ giúp sửa và bổ sung chi tiết cho.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn cậu nhiều lắm, sửa xong là mình nộp hồ sơ được luôn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào anh quản lý, tôi là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Trung thiếu nhi bán thời gian.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, bạn giới thiệu qua trình độ ngôn ngữ và thời gian rảnh của mình nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Tôi giao tiếp tiếng Trung hàng ngày khá trôi chảy, các buổi tối trong tuần và cả ngày cuối tuần tôi đều rảnh.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Bạn có kinh nghiệm tiếp xúc với trẻ nhỏ không, có giỏi tương tác trên lớp không?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây tôi từng phụ trách các em nhỏ trong các hoạt động ở trường, tôi rất thích giao tiếp với trẻ con.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Nhìn chung điều kiện của bạn phù hợp với yêu cầu công việc, trong ba ngày sẽ báo kết quả tuyển dụng cho bạn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Cảm ơn anh đã cho tôi cơ hội phỏng vấn, tôi sẽ kiên nhẫn chờ tin.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào chị, tôi đã đọc kỹ bản hợp đồng lao động thời vụ này, có một chỗ muốn xác nhận lại.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Bạn thắc mắc điều khoản nào, cứ nói thẳng ra nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi ngày hai mươi hàng tháng trả lương, nhưng lại không nêu rõ tiêu chuẩn phụ cấp làm thêm giờ.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Chi tiết lương làm thêm giờ được đính kèm ở trang phụ lục của hợp đồng, để tôi đưa cho bạn xem đối chiếu.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký điều khoản bổ sung, hai bên mỗi bên giữ một bản hợp đồng đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng vậy, một bản lưu tại cửa hàng, một bản do chính bạn giữ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi đã hiểu rõ toàn bộ điều khoản rồi, giờ tôi ký xác nhận.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资；学生备考类请假大多可以协调同事顶替，无需自行补工时。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，有一件事提前跟您沟通，下周三我无法到门店上班。','diàn zhǎng nín hǎo， yǒu yī jiàn shì tí qián gēn nín gōu tōng， xià zhōu sān wǒ wú fǎ dào mén diàn shàng bān。','Chào cửa hàng trưởng, có một việc tôi muốn báo trước, thứ Tư tuần sau tôi không thể đến cửa hàng làm việc.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'你先说说是什么原因，门店排班需要提前协调人员顶替岗位吧。','nǐ xiān shuō shuō shì shén me yuán yīn， mén diàn pái bān xū yào tí qián xié tiáo rén yuán dǐng tì gǎng wèi ba。','Bạn nói rõ lý do xem sao, vì lịch trực cửa hàng cần sắp xếp người thay ca trước.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'下周三全天进行汉语专业期末考试，从上午八点考到下午五点，全天都无法到岗，实在抱歉呢。','xià zhōu sān quán tiān jìn xíng hàn yǔ zhuān yè qī mò kǎo shì， cóng shàng wǔ bā diǎn kǎo dào xià wǔ wǔ diǎn， quán tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Thứ Tư tuần sau tôi phải thi hết môn chuyên ngành tiếng Trung cả ngày, từ tám giờ sáng đến năm giờ chiều, cả ngày không thể đến làm được, tôi thật sự xin lỗi.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'学生学业优先是理所应当的，你提前一周告知，我有充足时间调整整体排班。','xué shēng xué yè yōu xiān shì lǐ suǒ yīng dāng de， nǐ tí qián yī zhōu gào zhī， wǒ yǒu chōng zú shí jiān tiáo zhěng zhěng tǐ pái bān。','Việc học của sinh viên là ưu tiên hàng đầu, đương nhiên rồi, bạn báo trước cả tuần thế này thì tôi có đủ thời gian để sắp xếp lại lịch trực.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'我担心缺一天班次，月度工时达不到门店规定标准，影响当月薪资发放。','wǒ dān xīn quē yī tiān bān cì， yuè dù gōng shí dá bú dào mén diàn guī dìng biāo zhǔn， yǐng xiǎng dàng yuè xīn zī fā fàng。','Tôi chỉ lo là nghỉ mất một ca thì tổng giờ làm trong tháng không đạt tiêu chuẩn cửa hàng quy định, ảnh hưởng đến lương tháng này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'我会安排其他空闲同事顶替你的全天班次，不用有心理负担。','wǒ huì ān pái qí tā kòng xián tóng shì dǐng tì nǐ de quán tiān bān cì， bù yòng yǒu xīn lǐ fù dān。','Tôi sẽ sắp xếp đồng nghiệp khác rảnh để thay ca cả ngày cho bạn, đừng lo lắng gì cả.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'考完试之后，我可以主动多上两天晚班，补上本次缺失的工时。','kǎo wán shì zhī hòu， wǒ kě yǐ zhǔ dòng duō shàng liǎng tiān wǎn bān， bǔ shàng běn cì quē shī de gōng shí。','Sau khi thi xong, tôi có thể chủ động làm thêm hai ca tối để bù lại giờ làm bị thiếu lần này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_08','V382','店长',8,'不用刻意额外加班补工时，你后续正常出勤就满足月度最低工时要求。','bù yòng kè yì é wài jiā bān bǔ gōng shí， nǐ hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù zuì dī gōng shí yāo qiú。','Không cần cố tình làm thêm để bù giờ đâu, sau này bạn đi làm bình thường là đủ đạt mức giờ làm tối thiểu trong tháng rồi.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_09','V382','阮明',9,'太感谢店长体谅学生备考，我会提前一天完成手头所有工作交接。','tài gǎn xiè diàn zhǎng tǐ liàng xué shēng bèi kǎo， wǒ huì tí qián yī tiān wán chéng shǒu tóu suǒ yǒu gōng zuò jiāo jiē。','Cảm ơn cửa hàng trưởng đã thông cảm cho việc học của sinh viên, tôi sẽ bàn giao xong hết công việc trước một ngày.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_10','V382','店长',10,'交接不用复杂，把当日需要整理的货品清单留在收银台就行。','jiāo jiē bù yòng fù zá， bǎ dāng rì xū yào zhěng lǐ de huò pǐn qīng dān liú zài shōu yín tái jiù xíng。','Bàn giao không cần phức tạp đâu, chỉ cần để lại danh sách hàng hóa cần sắp xếp trong ngày ở quầy thu ngân là được.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_11','V382','阮明',11,'考试结束后我会第一时间回门店正常上班，不耽误后续排班。','kǎo shì jié shù hòu wǒ huì dì yī shí jiān huí mén diàn zhèng cháng shàng bān， bù dān wù hòu xù pái bān。','Sau khi thi xong tôi sẽ quay lại cửa hàng làm việc bình thường ngay, không làm ảnh hưởng đến lịch trực sau đó.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_12','V382','店长',12,'专心备考，不用分心担心门店工作。','zhuān xīn bèi kǎo， bù yòng fēn xīn dān xīn mén diàn gōng zuò。','Cứ tập trung ôn thi đi, đừng phân tâm lo lắng chuyện cửa hàng làm gì.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_13','V382','阮明',13,'我一定好好复习，不辜负您的包容。','wǒ yí dìng hǎo hǎo fù xí， bù gū fù nín de bāo róng。','Tôi nhất định sẽ ôn tập thật tốt, không phụ lòng bao dung của cửa hàng trưởng.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_14','V382','店长',14,'有任何考试变动提前跟我说，方便我重新调班。','yǒu rèn hé kǎo shì biàn dòng tí qián gēn wǒ shuō， fāng biàn wǒ chóng xīn diào bān。','Nếu có thay đổi gì về lịch thi thì báo trước cho tôi, để tôi tiện sắp xếp lại ca trực.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_15','V382','阮明',15,'多谢店长体谅！','duō xiè diàn zhǎng tǐ liàng！','Cảm ơn cửa hàng trưởng nhiều lắm ạ!',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào chị, tôi muốn xác nhận lại mức lương theo giờ và hình thức trả lương của công việc bán thời gian này.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Hai mươi hai tệ một giờ, ngày hai mươi hàng tháng sẽ chuyển khoản qua thẻ ngân hàng nhé.','AM03') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ tiền bảo hiểm xã hội hay các loại phí thủ tục nào khác không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không phải đóng bảo hiểm xã hội, lương thực nhận không bị trừ khoản nào cả.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_05','V383','阮明',5,'只能绑定国内银行卡接收工资对吧？','zhǐ néng bǎng dìng guó nèi yín háng kǎ jiē shōu gōng zī duì ba？','Chỉ có thể nhận lương qua thẻ ngân hàng trong nước thôi đúng không ạ?','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_06','V383','人事专员',6,'是的，境外银行卡无法对接公司财务系统。','shì de， jìng wài yín háng kǎ wú fǎ duì jiē gōng sī cái wù xì tǒng。','Đúng vậy, thẻ ngân hàng nước ngoài không kết nối được với hệ thống tài chính của công ty.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_07','V383','阮明',7,'明白了，我尽快办理专用工资卡。','míng bái le， wǒ jǐn kuài bàn lǐ zhuān yòng gōng zī kǎ。','Tôi hiểu rồi, tôi sẽ làm thẻ lương riêng càng sớm càng tốt.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT384','S127','Hỏi về việc đóng thuế thu nhập làm thêm',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V384','SIT384','P1','twist','chinh_thuc',NULL,'国内劳务报酬设有免税额度，用人单位统一代扣个税，完税证明可用于留学生签证续办。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_01','V384','阮明',1,'您好，留学生兼职获得的收入，需要申报个人所得税吗？','nín hǎo， liú xué shēng jiān zhí huò dé de shōu rù， xū yào shēn bào gè rén suǒ dé shuì ma？','Xin chào, thu nhập từ việc làm thêm của du học sinh có cần khai thuế thu nhập cá nhân không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_02','V384','财务',2,'月度收入超过八百元，超出部分需要缴纳劳务个税哈。','yuè dù shōu rù chāo guò bā bǎi yuán， chāo chū bù fèn xū yào jiǎo nà láo wù gè shuì hā。','Thu nhập hàng tháng vượt quá tám trăm tệ thì phần vượt phải nộp thuế thu nhập cá nhân đối với thù lao dịch vụ nhé.','AM06') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_03','V384','阮明',3,'个税会直接从当月工资里扣除，还是我自行申报嘛？','gè shuì huì zhí jiē cóng dàng yuè gōng zī lǐ kòu chú， hái shì wǒ zì xíng shēn bào ma？','Vậy thuế thu nhập cá nhân sẽ bị trừ trực tiếp từ lương tháng đó, hay tôi phải tự kê khai vậy ạ?','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_04','V384','财务',4,'公司统一代扣代缴，工资条会标注扣税明细。','gōng sī tǒng yí dài kòu dài jiǎo， gōng zī tiáo huì biāo zhù kòu shuì míng xì。','Công ty sẽ khấu trừ và nộp thay thống nhất, trên phiếu lương sẽ ghi rõ chi tiết khoản thuế bị trừ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_05','V384','阮明',5,'年末可以打印全年纳税记录用作签证材料吗？','nián mò kě yǐ dǎ yìn quán nián nà shuì jì lù yòng zuò qiān zhèng cái liào ma？','Cuối năm tôi có thể in bảng ghi nhận nộp thuế cả năm để dùng làm hồ sơ visa được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_06','V384','财务',6,'可以，年末我统一打印完整纳税单据交给你。','kě yǐ， nián mò wǒ tǒng yī dǎ yìn wán zhěng nà shuì dān jù jiāo gěi nǐ。','Được chứ, cuối năm tôi sẽ in đầy đủ chứng từ nộp thuế cả năm đưa cho bạn.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_07','V384','阮明',7,'好，相关规则我记下来，感谢细致讲解。','hǎo， xiāng guān guī zé wǒ jì xià lái， gǎn xiè xì zhì jiǎng jiě。','Vâng, tôi đã ghi nhớ các quy định này rồi, cảm ơn đã giải thích cặn kẽ.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT385','S128','Mở tài khoản ngân hàng riêng để nhận lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V385','SIT385','P1','suon_se','chinh_thuc',NULL,'外籍留学生凭护照、在校证明可办理学生储蓄卡，多数银行学生账户免除年费与小额管理费。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_01','V385','阮明',1,'您好，我是在校留学生，想开一张储蓄卡专门接收兼职工资。','nín hǎo， wǒ shì zài xiào liú xué shēng， xiǎng kāi yī zhāng chǔ xù kǎ zhuān mén jiē shōu jiān zhí gōng zī。','Chào chị, tôi là du học sinh đang học tại trường, muốn mở một thẻ tiết kiệm riêng để nhận lương làm thêm.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_02','V385','柜员',2,'请出示你的护照、在校学生证，填写开户申请单吧。','qǐng chū shì nǐ de hù zhào、 zài xiào xué shēng zhèng， tián xiě kāi hù shēn qǐng dān ba。','Bạn cho tôi xem hộ chiếu và thẻ sinh viên, rồi điền vào đơn đăng ký mở tài khoản nhé.','AM07') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_03','V385','阮明',3,'这张卡只用来收工资，平时不存放大额资金可以吗？','zhè zhāng kǎ zhǐ yòng lái shōu gōng zī， píng shí bù cún fàng dà é zī jīn kě yǐ ma？','Thẻ này chỉ dùng để nhận lương thôi, bình thường không để số tiền lớn trong đó có được không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_04','V385','柜员',4,'完全没问题，普通一类储蓄卡支持企业对公转账呢。','wán quán méi wèn tí， pǔ tōng yī lèi chǔ xù kǎ zhī chí qǐ yè duì gōng zhuàn zhàng ne。','Hoàn toàn không vấn đề gì, thẻ tiết kiệm loại một thông thường vẫn hỗ trợ chuyển khoản từ doanh nghiệp mà.','AM04') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_05','V385','阮明',5,'开户有没有年费、短信通知这类额外收费项目？','kāi hù yǒu méi yǒu nián fèi、 duǎn xìn tōng zhī zhè lèi é wài shōu fèi xiàng mù？','Mở tài khoản có phát sinh phí thường niên, phí tin nhắn thông báo hay khoản phí nào khác không ạ?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_06','V385','柜员',6,'学生账户免年费，免费开通资金变动短信提醒。','xué shēng zhàng hù miǎn nián fèi， miǎn fèi kāi tōng zī jīn biàn dòng duǎn xìn tí xǐng。','Tài khoản sinh viên được miễn phí thường niên, và được miễn phí đăng ký nhận tin nhắn thông báo biến động số dư.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_07','V385','阮明',7,'好，我现在填写单据办理开户手续。','hǎo， wǒ xiàn zài tián xiě dān jù bàn lǐ kāi hù shǒu xù。','Vâng, giờ tôi điền vào đơn để làm thủ tục mở tài khoản.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT386','S127','Xin nghỉ việc trước thời hạn hợp đồng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V386','SIT386','P1','twist','ban_chinh_thuc',NULL,'国内临时劳务用工规范要求员工提前三十天申请离职，企业可根据门店人手、员工实际情况适度放宽离职期限；离职必须填写书面申请存档，口头离职不生效。') ON CONFLICT (id) DO UPDATE SET situation_id=EXCLUDED.situation_id,persona_id=EXCLUDED.persona_id,outcome_type=EXCLUDED.outcome_type,register_level=EXCLUDED.register_level,context_note=EXCLUDED.context_note,cultural_note=EXCLUDED.cultural_note;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_01','V386','阮明',1,'店长，我今天过来跟您沟通离职事宜，下学期专业课数量大幅增加。','diàn zhǎng， wǒ jīn tiān guò lái gēn nín gōu tōng lí zhí shì yí， xià xué qī zhuān yè kè shù liàng dà fú zēng jiā。','Chào chị quản lý, hôm nay em đến để trao đổi về việc xin nghỉ việc, học kỳ tới số lượng môn chuyên ngành tăng lên nhiều quá.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_02','V386','店长',2,'我大致了解留学生课程安排，你计划什么时候正式结束兼职工作？','wǒ dà zhì liǎo jiě liú xué shēng kè chéng ān pái， nǐ jì huà shén me shí hòu zhèng shì jié shù jiān zhí gōng zuò？','Chị cũng nắm sơ qua lịch học của du học sinh rồi, vậy em định khi nào chính thức nghỉ làm thêm?',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_03','V386','阮明',3,'原本合同约定做到学期末，我想申请提前半个月办理离职手续。','yuán běn hé tóng yuē dìng zuò dào xué qī mò， wǒ xiǎng shēn qǐng tí qián bàn gè yuè bàn lǐ lí zhí shǒu xù。','Ban đầu hợp đồng ghi làm đến cuối học kỳ, nhưng em muốn xin nghỉ sớm nửa tháng để làm thủ tục.',NULL) ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_04','V386','店长',4,'门店劳务用工有统一规范，离职需要提前三十天书面提交申请，只提前半个月不符合规定嘛。','mén diàn láo wù yòng gōng yǒu tǒng yī guī fàn， lí zhí xū yào tí qián sān shí tiān shū miàn tí jiāo shēn qǐng， zhǐ tí qián bàn gè yuè bù fú hé guī dìng ma。','Quy định lao động của cửa hàng là nghỉ việc phải báo trước bằng văn bản ba mươi ngày, chỉ báo trước nửa tháng thì không đúng quy định đâu.','AM09') ON CONFLICT (id) DO UPDATE SET variant_id=EXCLUDED.variant_id,speaker=EXCLUDED.speaker,order_index=EXCLUDED.order_index,text_zh=EXCLUDED.text_zh,pinyin=EXCLUDED.pinyin,text_vi=EXCLUDED.text_vi,attitude_marker_id=EXCLUDED.attitude_marker_id;
